import React, { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { Link } from "react-router-dom";
import LoadingComponent from "../../components/Loading";
import ErrorDisplayMessage from "../../components/ErrorDisplayMessage";
import {
  fetchAllExpAction,
  deleteExpAction,
} from "../../redux/slices/expenses/expenseStatSlice";
import "../../App.css";

const ExpenseList = () => {
  const dispatch = useDispatch();

  useEffect(() => {dispatch(fetchAllExpAction());
    
  }, [dispatch]);

  const expenseState = useSelector((state) => state?.expense);
  const { loading, appErr, serverErr, expenseList, isDeleted } = expenseState || {};

  useEffect(() => {
    if (isDeleted) {
      dispatch(fetchAllExpAction());
    }
  }, [isDeleted, dispatch]);

  const handleDelete = (id) => {
    const ok = window.confirm("Are you sure you want to delete this expense?");
    if (ok) dispatch(deleteExpAction(id));  
  };

  return (
    <section className="app-container">
      {loading ? (
        <LoadingComponent />
      ) : appErr || serverErr ? (
        <ErrorDisplayMessage>
          {serverErr} {appErr}
        </ErrorDisplayMessage>
      ) : (
        
        <div className="panel">
          <div className="panel-header">
            <div>
              <h2 className="panel-title">Expense Transactions</h2>
              <p className="panel-subtitle">View and manage all expense records</p>
            </div>

            <Link to="/add-expense" className="btn btn-primary">
              + Add Expense
            </Link>
          </div>

          {expenseList?.length ? (
            <div className="table-wrap">
              <table className="table table-modern">
                <thead>
                  <tr>
                    <th>Title</th>
                    <th>Amount</th>
                    <th>Date</th>
                    <th>Note</th>
                    <th>Type</th>
                    <th style={{ width: "180px" }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {expenseList.map((item) => (
                    <tr key={item._id}>
                      <td>{item.title}</td>
                      <td className="text-danger fw-bold">Rs. {item.amount}</td>
                      <td>{item.date ? new Date(item.date).toLocaleDateString() : "-"}</td>
                      <td>{item.note}</td>
                      <td>
                        <span className="badge-expense">{item.type || "expense"}</span>
                      </td>
                      <td>
                        <div className="row-actions">
                          <Link to="/edit" className="btn btn-sm btn-outline-primary">
                            Edit
                          </Link>
                          <button
                            type="button"
                            className="btn btn-sm btn-outline-danger"
                            onClick={() => handleDelete(item._id)}
                          >
                            Delete
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="panel mt-3 text-center">
              <p className="muted mb-0">No expense transactions found.</p>
            </div>
          )}
        </div>
      )}
    </section>
  );
};

export default ExpenseList;
